// Checks that slides stay on the e2e design system.
//
//   pnpm check              reads every slide file and reports rule breaks
//   pnpm check <deck>       the same, then opens the deck in a headless browser and
//                           reports text that leaves the slide, missing images and
//                           which typeface it rendered in
//   pnpm check --stamp <file>   writes the source stamp into a translated slide
//
// The rules come from brand.md. A rule that fails here is a rule, not a suggestion:
// fix the slide, do not edit this file.
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { deckNames, entryOf } from "./deck.mjs";

const root = resolve(import.meta.dirname, "..");
const args = process.argv.slice(2);

/** Spacing scale in px (brand.md, hard rule 10). 0 and 1 px are allowed for resets and hairlines. */
const SCALE = new Set([0, 1, 4, 8, 20, 40, 80, 120, 320]);
/** Slidev's own components, allowed next to the theme's. */
const BUILT_IN = new Set(["Transition", "TransitionGroup", "Teleport", "Suspense", "KeepAlive", "Component"]);
const SLIDEV = new Set(["Arrow", "VDragArrow", "AutoFitText", "LightOrDark", "Link", "RenderWhen", "SlideCurrentNo", "SlidesTotal", "Toc", "Transform", "Tweet", "VAfter", "VClick", "VClicks", "VSwitch", "Youtube", "SlidevVideo", "CodeBlockWrapper", "Mermaid", "PlantUml", "Monaco"]);
const components = new Set(
  readdirSync(join(root, "theme", "components")).map((f) => f.replace(/\.vue$/, "")),
);

/** @type {{file: string, line: number, rule: string, message: string, level: "error" | "warn"}[]} */
const findings = [];
/** Records one finding. */
function report(file, line, rule, message, level = "error") {
  findings.push({ file: relative(root, file), line, rule, message, level });
}

/** The short content hash that ties a translated slide to the English slide it came from. */
function stampOf(file) {
  return createHash("sha1").update(readFileSync(file)).digest("hex").slice(0, 8);
}

/** Every markdown file under a folder. */
function markdownIn(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return name === "node_modules" ? [] : markdownIn(path);
    return name.endsWith(".md") && name !== "README.md" ? [path] : [];
  });
}

/**
 * Blanks out fenced code and inline code, keeping line numbers, so code samples are not
 * read as slide markup.
 * @param {string} text slide source
 */
function withoutCode(text) {
  const blank = (match) => match.replace(/[^\n]/g, " ");
  return text.replace(/^(`{3,})[^\n]*\n[\s\S]*?^\1`*\s*$/gm, blank).replace(/`[^`\n]*`/g, blank);
}

/** Line number of a character offset. */
const lineAt = (text, index) => text.slice(0, index).split("\n").length;

/** Checks one utility class against the spacing, colour, type and shape rules. */
function checkClass(file, line, raw) {
  const name = raw.replace(/^!/, "").replace(/^([a-z0-9-]+:)+/, "").replace(/^!/, "").replace(/^-/, "");

  const spacing = name.match(/^(?:m|p|gap|space)(?:[trblxyse]|-x|-y)?-(.+)$/);
  if (spacing) {
    const value = spacing[1];
    const px = value.match(/^\[(-?\d+(?:\.\d+)?)px\]$/);
    const step = value.match(/^(\d+(?:\.\d+)?)$/);
    const size = px ? Math.abs(Number(px[1])) : step ? Number(step[1]) * 4 : undefined;
    if (size !== undefined && !SCALE.has(size)) {
      report(file, line, "spacing", `"${raw}" is ${size}px. Spacing comes from the scale only: 4, 8, 20, 40, 80, 120, 320.`);
    } else if (size === undefined && !/^(auto|px|0)$/.test(value) && /^\[/.test(value)) {
      report(file, line, "spacing", `"${raw}" is not a px value from the scale: 4, 8, 20, 40, 80, 120, 320.`);
    }
    return;
  }

  const colour = name.match(/^(?:text|bg|border(?:-[trblxy])?|outline|ring|fill|stroke|decoration|divide|from|via|to)-(.+)$/);
  if (colour) {
    const value = colour[1];
    if (/^\[(#|rgb|hsl|oklch|color)/i.test(value)) {
      report(file, line, "colour", `"${raw}" is a raw colour. Use the brand tokens: text-e2e-blank, bg-e2e-pipeline, border-e2e-neutral-700.`);
    } else if (/^(white|black|slate|gray|grey|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)(-\d{2,3})?(\/\d+)?$/.test(value)) {
      report(file, line, "colour", `"${raw}" is not a brand colour. Use an e2e token such as ${name.split("-")[0]}-e2e-neutral-400.`);
    }
  }

  if (/^font-(thin|extralight|light|medium|semibold|bold|extrabold|black|\[\d+\])$/.test(name) || name === "italic") {
    report(file, line, "weight", `"${raw}": e2e sets one weight, Regular 400, and no italics.`);
  }
  if (/^font-(serif|\[)/.test(name)) {
    report(file, line, "typeface", `"${raw}": the only faces are font-sans, font-heading, font-mono and font-code.`);
  }
  if (/^(uppercase|capitalize)$/.test(name)) {
    report(file, line, "case", `"${raw}": capitals appear only in a <Badge>. Headlines and labels are lowercase.`);
  }
  if (/^rounded(-|$)/.test(name) && !/^rounded-none$/.test(name)) {
    report(file, line, "shape", `"${raw}": no rounded corners.`);
  }
  if (/^(shadow|drop-shadow|blur|backdrop-blur)(-|$)/.test(name) && !/-none$/.test(name)) {
    report(file, line, "shape", `"${raw}": no shadows and no blur.`);
  }
  if (/^bg-(gradient|linear|radial|conic)/.test(name)) {
    report(file, line, "shape", `"${raw}": no gradients. Surfaces are flat Terminal, Pipeline or Blank.`);
  }
  if (/^(rotate|skew)(-|$)/.test(name)) {
    report(file, line, "shape", `"${raw}": nothing is rotated or skewed. Every edge sits on the row grid.`);
  }
}

/** Reads one slide file and reports every rule it breaks. */
function checkFile(file) {
  const text = readFileSync(file, "utf8");
  const markup = withoutCode(text);

  for (const match of text.matchAll(/[–—]/g)) {
    report(file, lineAt(text, match.index), "dash", "Em and en dashes are not used. Write a comma, a full stop or a hyphen.");
  }

  for (const match of markup.matchAll(/(?<![\w-]):?class="([^"]*)"/g)) {
    const line = lineAt(markup, match.index);
    for (const token of match[1].split(/[\s'"`,]+/)) {
      if (/^!?-?[a-z][\w:.\-[\]/%#()!]*$/.test(token)) checkClass(file, line, token);
    }
  }

  const styled = [
    ...markup.matchAll(/(?<![\w-]):?style="([^"]*)"/g),
    ...markup.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/g),
  ];
  for (const match of styled) {
    const line = lineAt(markup, match.index);
    const css = match[1];
    if (/#[0-9a-f]{3,8}\b|rgba?\(|hsla?\(/i.test(css)) report(file, line, "colour", "A raw colour in a style. Use a token: var(--e2e-blank), var(--e2e-neutral-700).");
    if (/font-family/i.test(css)) report(file, line, "typeface", "Do not set font-family. Use the font-sans or font-mono classes.");
    if (/font-weight\s*:\s*(?!400|normal)/i.test(css)) report(file, line, "weight", "e2e sets one weight, Regular 400.");
    if (/border-radius\s*:\s*(?!0)/i.test(css)) report(file, line, "shape", "No rounded corners.");
    if (/box-shadow|text-shadow|filter\s*:|gradient\(/i.test(css)) report(file, line, "shape", "No shadows, blur or gradients.");
    if (/text-transform\s*:\s*(uppercase|capitalize)/i.test(css)) report(file, line, "case", "Capitals appear only in a <Badge>.");
  }

  for (const match of markup.matchAll(/^#{1,3} (.+)$/gm)) {
    if (/!|…|\.\.\./.test(match[1])) {
      report(file, lineAt(markup, match.index), "headline", "Headlines carry no exclamation marks and no ellipsis.");
    }
  }

  for (const match of markup.matchAll(/<(b|i|em|u|font|center)(\s|>)/g)) {
    report(file, lineAt(markup, match.index), "weight", `<${match[1]}> is not used. e2e sets one weight and no italics.`);
  }

  for (const match of markup.matchAll(/<([A-Z][A-Za-z0-9]*)/g)) {
    const tag = match[1];
    if (!components.has(tag) && !SLIDEV.has(tag) && !BUILT_IN.has(tag)) {
      report(file, lineAt(markup, match.index), "component", `<${tag}> is not a component of the theme. The list is in theme/components and in patterns/slides.md.`);
    }
  }

  if (/e2e-(logotype|sign)[\w-]*\.(svg|png)/.test(markup)) {
    report(file, 1, "logo", "The logo is placed by the layouts, in the top rail. Do not add it to a slide.");
  }

  for (const match of markup.matchAll(/\bsrc="(?!https?:|data:|\{)([^"]+)"/g)) {
    const src = match[1];
    const path = src.startsWith("/") ? join(dirname(file), "public", src) : resolve(dirname(file), src);
    // A shared slide cannot know which deck's public folder it is shown from.
    if (src.startsWith("/") && !file.includes(`${join(root, "decks")}/`)) continue;
    if (!existsSync(path)) report(file, lineAt(markup, match.index), "asset", `"${src}" does not exist.`);
  }

  for (const match of text.matchAll(/^src: (.+)$/gm)) {
    if (!existsSync(resolve(dirname(file), match[1].trim()))) {
      report(file, lineAt(text, match.index), "import", `The slide "${match[1].trim()}" does not exist.`);
    }
  }
}

/** Checks a deck's headmatter. */
function checkDeck(file) {
  const text = readFileSync(file, "utf8");
  const head = text.match(/^---\n([\s\S]*?)\n---/)?.[1] ?? "";
  if (!/^theme: e2e\s*$/m.test(head.split("\n")[0] ?? "")) {
    report(file, 2, "headmatter", 'The headmatter starts with "theme: e2e".');
  }
  const name = relative(join(root, "decks"), dirname(file));
  if (name === "main" || file.includes(`${join(root, "patterns")}`)) return;
  for (const [key, placeholder] of [["presenter", "Your Name"], ["event", "Your Meetup"], ["date", "month 2026"]]) {
    const value = head.match(new RegExp(`^${key}: (.*)$`, "m"))?.[1]?.trim();
    if (!value) report(file, 2, "headmatter", `Set "${key}" in the headmatter.`);
    else if (value === placeholder) report(file, 2, "headmatter", `"${key}" still holds the placeholder "${placeholder}".`, "warn");
  }
}

/** Checks that every translated slide names the English slide version it was made from. */
function checkTranslations() {
  const slides = join(root, "slides");
  for (const lang of readdirSync(slides)) {
    if (lang === "en" || !statSync(join(slides, lang)).isDirectory()) continue;
    for (const file of markdownIn(join(slides, lang))) {
      const source = join(slides, "en", relative(join(slides, lang), file));
      if (!existsSync(source)) {
        report(file, 1, "translation", "There is no English slide with this name in slides/en.", "warn");
        continue;
      }
      const stamp = readFileSync(file, "utf8").match(/^source: (\w+)\s*$/m)?.[1];
      if (!stamp) {
        report(file, 1, "translation", `Add the source stamp: pnpm check --stamp ${relative(root, file)}`);
      } else if (stamp !== stampOf(source)) {
        report(file, 1, "translation", `The English slide changed since this translation. Update the translation, then: pnpm check --stamp ${relative(root, file)}`, "warn");
      }
    }
  }
}

/** Writes the current stamp of the English slide into a translated slide's frontmatter. */
function stamp(target) {
  const file = resolve(target);
  const slides = join(root, "slides");
  const [, ...rest] = relative(slides, file).split("/");
  const source = join(slides, "en", ...rest);
  if (!existsSync(file) || !existsSync(source)) {
    console.error(`cannot stamp ${target}: it needs a twin in slides/en`);
    process.exit(1);
  }
  const text = readFileSync(file, "utf8");
  const line = `source: ${stampOf(source)}`;
  const next = /^source: .*$/m.test(text)
    ? text.replace(/^source: .*$/m, line)
    : /^---\n/.test(text)
      ? text.replace(/^---\n/, `---\n${line}\n`)
      : `---\n${line}\n---\n\n${text}`;
  writeFileSync(file, next);
  console.log(`${relative(root, file)}: ${line}`);
}

/**
 * Opens a deck in a headless browser and reports what only a render can show.
 * @param {string} name deck name
 * @param {string} entry absolute path to its slides.md
 */
async function checkRender(name, entry) {
  let chromium;
  try {
    ({ chromium } = await import("playwright-chromium"));
  } catch {
    console.error("the render check needs a browser: pnpm exec playwright install chromium");
    process.exit(1);
  }
  const slidev = fileURLToPath(import.meta.resolve("@slidev/cli/bin/slidev.mjs"));
  const port = 3300 + Math.floor(Math.random() * 500);
  const server = spawn(process.execPath, [slidev, entry, "--port", String(port), "--open", "false"], {
    stdio: "ignore",
  });
  const base = `http://localhost:${port}`;
  const flag = args.indexOf("--executable-path");
  let browser;
  try {
    for (let tries = 0; ; tries++) {
      try {
        if ((await fetch(base)).ok) break;
      } catch {}
      if (tries > 120) throw new Error("the deck did not start");
      await new Promise((done) => setTimeout(done, 250));
    }
    browser = await chromium.launch(flag === -1 ? {} : { executablePath: args[flag + 1] });
    const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
    await page.goto(`${base}/1`, { waitUntil: "networkidle" });
    await page.waitForSelector(".slidev-layout");
    const total = await page.evaluate(() => {
      const nav = globalThis.__slidev__?.nav;
      return nav?.total?.value ?? nav?.total;
    });
    if (!Number.isInteger(total)) throw new Error("could not read the number of slides");
    for (let no = 1; no <= total; no++) {
      await page.goto(`${base}/${no}?clicks=99`, { waitUntil: "networkidle" });
      try {
        await page.waitForSelector(`.slidev-page-${no} .slidev-layout`, { timeout: 10000 });
      } catch {
        report(entry, no, "render", `Slide ${no} did not render. Run pnpm dev ${name} and open slide ${no} to see the error.`);
        continue;
      }
      await page.evaluate(() => document.fonts.ready);
      await page.waitForTimeout(400);
      const result = await page.evaluate((current) => {
        const slide = document.querySelector(`.slidev-page-${current} .slidev-layout`);
        const frame = slide.getBoundingClientRect();
        const scale = frame.width / 1280;
        const out = [];
        const missing = [];
        const hidden = (el) => el.closest("[aria-hidden='true'], .pointer-events-none") !== null;
        for (const el of slide.querySelectorAll("*")) {
          if (hidden(el)) continue;
          const style = getComputedStyle(el);
          if (style.display === "none" || style.visibility === "hidden") continue;
          const media = ["IMG", "VIDEO", "SVG", "TABLE", "PRE"].includes(el.tagName.toUpperCase());
          const text = [...el.childNodes].some((n) => n.nodeType === 3 && n.textContent.trim());
          if (!media && !text) continue;
          if (el.tagName === "IMG" && el.complete && el.naturalWidth === 0) missing.push(el.getAttribute("src"));
          let box = el.getBoundingClientRect();
          if (text && !media) {
            const range = document.createRange();
            range.selectNodeContents(el);
            box = range.getBoundingClientRect();
          }
          if (box.width === 0 && box.height === 0) continue;
          const over = Math.max(frame.left - box.left, box.right - frame.right, frame.top - box.top, box.bottom - frame.bottom) / scale;
          if (over > 1.5) out.push({ what: (el.textContent.trim().slice(0, 60) || `<${el.tagName.toLowerCase()}>`), by: Math.round(over) });
          if (el.scrollWidth > el.clientWidth + 2 && style.overflowX !== "visible" && text) out.push({ what: el.textContent.trim().slice(0, 60), by: el.scrollWidth - el.clientWidth });
        }
        return { out, missing, font: document.documentElement.dataset.e2eFont, lang: document.documentElement.lang };
      }, no);
      if (result.out.length) {
        const worst = result.out.reduce((a, b) => (b.by > a.by ? b : a));
        const more = result.out.length > 1 ? ` (and ${result.out.length - 1} more)` : "";
        report(entry, no, "overflow", `Slide ${no}: "${worst.what}" leaves the slide by ${worst.by}px${more}. Shorten the copy or split the slide; never shrink the type.`);
      }
      for (const src of result.missing) report(entry, no, "asset", `Slide ${no}: the image "${src}" did not load.`);
      if (no === total) {
        console.log(
          result.font === "cassette"
            ? `${name}: ${total} slides rendered in Cassette`
            : `${name}: ${total} slides rendered in Geist, the fallback. Cassette is not installed: see theme/assets/fonts/README.md`,
        );
      }
    }
  } finally {
    await browser?.close();
    server.kill();
  }
}

if (args[0] === "--stamp") {
  if (!args[1]) {
    console.error("usage: pnpm check --stamp slides/<lang>/<topic>.md");
    process.exit(1);
  }
  stamp(args[1]);
  process.exit(0);
}

const deck = args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--executable-path");
if (deck && !entryOf(deck)) {
  console.error(`there is no deck called "${deck}"\ndecks: ${deckNames().join(", ")}`);
  process.exit(1);
}

const files = [...markdownIn(join(root, "slides")), ...markdownIn(join(root, "decks")), ...markdownIn(join(root, "patterns"))];
for (const file of files) checkFile(file);
for (const name of deckNames()) checkDeck(entryOf(name));
checkTranslations();
if (deck) await checkRender(deck, entryOf(deck));

findings.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line);
for (const f of findings) {
  console.log(`${f.level === "error" ? "error" : "warn "}  ${f.file}:${f.line}  [${f.rule}] ${f.message}`);
}
const errors = findings.filter((f) => f.level === "error").length;
const warnings = findings.length - errors;
console.log(
  findings.length
    ? `\n${errors} ${errors === 1 ? "error" : "errors"}, ${warnings} ${warnings === 1 ? "warning" : "warnings"} in ${files.length} files`
    : `${files.length} files checked, nothing to fix`,
);
process.exit(errors ? 1 : 0);
